    if n % x == 0:
      new = f'{term[x]}*{factor[n//x]}'
      if term[n] is None or len(term[n]) > len(new):
        term[n] = new

  if number[n] is not None:
    factor[n] = number[n]

  for _ in range(2):
    if term[n] is None or (factor[n] is not None and len(term[n]) > len(factor[n])):
      term[n] = factor[n]
